'use strict';
window.AdaptiveLayout={
 refresh(){const en=I18n.language==='en';
  const sidebar=document.querySelector('.sidebar'),nav=sidebar?.querySelector('nav');if(nav&&innerWidth>900){const links=[...nav.querySelectorAll('a')].filter(a=>!a.hidden&&getComputedStyle(a).display!=='none'),available=nav.getBoundingClientRect().height;const row=Math.max(25,Math.min(35,Math.floor((available-(links.length-1)*2)/Math.max(1,links.length))));document.documentElement.style.setProperty('--ux10-nav-row',row+'px');document.documentElement.style.setProperty('--ux10-nav-width',en?'258px':'238px');}
  for(const menu of document.querySelectorAll('.sidebar nav,.mobile-primary')){const current=new URL(location.href),ranked=[...menu.querySelectorAll('a[data-primary-route]')].map(a=>{const url=new URL(a.href),query=[...url.searchParams];const match=(current.pathname===url.pathname||current.pathname.startsWith(url.pathname+'/'))&&query.every(([k,v])=>current.searchParams.get(k)===v);return {a,score:match?url.pathname.length+query.length*100:-1};}).sort((a,b)=>b.score-a.score);if(ranked[0]?.score>=0){for(const {a}of ranked){const active=a===ranked[0].a;a.classList.toggle('nav-active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');}const crumb=document.querySelector('.breadcrumb strong');if(crumb)crumb.textContent=ranked[0].a.querySelector('.ux-nav-label')?.textContent||crumb.textContent;}}
  for(const cell of document.querySelectorAll('#page-content th,#page-content td'))if(!cell.querySelector('input,select,textarea')&&cell.textContent.trim())cell.title=cell.textContent.trim();
  const canvas=document.createElement('canvas'),measure=canvas.getContext('2d');for(const grid of document.querySelectorAll('#page-content .form-grid')){let minimum=240;for(const label of [...grid.children].filter(e=>e.tagName==='LABEL')){const text=[...label.childNodes].filter(n=>n.nodeType===Node.TEXT_NODE).map(n=>n.textContent).join('').trim();measure.font=getComputedStyle(label).font;const width=Math.ceil(measure.measureText(text).width)+16;if(width<=340)minimum=Math.max(minimum,width);label.classList.toggle('ux10-one-line-label',width<=Math.max(0,label.clientWidth)&&!label.classList.contains('gate-check'));}grid.style.setProperty('--ux10-field-min',minimum+'px');}
 },
 queue(){clearTimeout(this.timer);this.timer=setTimeout(()=>this.refresh(),30);}
};
const ux10LayoutShow=Router.performShow.bind(Router);Router.performShow=async function(...args){const result=await ux10LayoutShow(...args);AdaptiveLayout.refresh();AdaptiveLayout.queue();return result;};
window.addEventListener('resize',()=>AdaptiveLayout.queue());
const ux10LayoutInit=Router.init.bind(Router);Router.init=async function(...args){const result=await ux10LayoutInit(...args);AdaptiveLayout.refresh();const sidebar=document.querySelector('.sidebar');if(sidebar)new ResizeObserver(()=>AdaptiveLayout.queue()).observe(sidebar);return result;};
